	ALTER TABLE [metrics].[AssetVersionCondition] CHECK CONSTRAINT [FK_MetricAssetVersionCondition_MetricAssetVersion];
end

if not exists (select * from [sys].[default_constraints] where [type] = 'D' and name = 'DF_MetricAssetVersionCondition_AssetVersionUid')
begin
