begin
	ALTER TABLE [metrics].[AssetVersionCondition] ADD CONSTRAINT [DF_MetricAssetVersionCondition_Uid] DEFAULT (newid()) FOR [Uid]
end

if not exists (select * from [sys].[default_constraints] where [type] = 'D' and name = 'DF_MetricAssetVersionCondition_MatchType')
begin
	ALTER TABLE [metrics].[AssetVersionCondition] ADD CONSTRAINT [DF_MetricAssetVersionCondition_MatchType] DEFAULT ((1)) FOR [MatchType]
end

if not exists (select * from [sys].[default_constraints] where [type] = 'D' and name = 'DF_MetricAssetVersionCondition_Position')
